import { useSetRecoilState } from "recoil";
import IToDo from "../interfaces/IToDo";
import { toDoListState } from "../atoms";
import { ButtonHTMLAttributes, ReactElement } from "react";

function ToDo({ id, text, category }: IToDo) {
	const setToDoList = useSetRecoilState(toDoListState);

	// const onClick = (event: React.MouseEvent<HTMLButtonElement>) => {
	// 	console.log(event.currentTarget.name)
	// 	const {currentTarget: {name},} = event;
	// 	const newCategory: IToDo["category"] = name === "TODO" ? "TO_DO" 
	// 																					: name === "DOING" ? "DOING" 
	// 																						: "DONE"  
	// 	setToDoList(oldToDoList => {
	// 		const newList = oldToDoList.map( todo => {
	// 			return todo.id === id ? {id: todo.id, text: todo.text, category: newCategory} : todo
	// 		});

	// 		return newList;
	// 	});
	// }

	const onClick = (event: React.MouseEvent<HTMLButtonElement>) => {
		const {currentTarget: {name},} = event;
		const newCategory: IToDo["category"] = name === "TODO" ? "TO_DO" 
																						: name === "DOING" ? "DOING" 
																							: "DONE"  
		setToDoList(oldToDoList => {
			const targetIdx = oldToDoList.findIndex( todo => todo.id === id );
			oldToDoList[targetIdx].category = newCategory
			return oldToDoList;
		});
	}



	return (
		<li>
			<span>{text}</span>
			{category !== "TO_DO" && <button name="TODO" onClick={onClick}>TODO</button>}
			{category !== "DOING" && <button name="DOING" onClick={onClick}>DOING</button>}
			{category !== "DONE" && <button name="DONE" onClick={onClick}>DONE</button>}
		</li>
	);
}

export default ToDo;
